$want = @('context:geometric','context:geometric-breaking-the-system','context:geometric-color-light-and-geometric-space','context:geometric-geometry-built-for-the-body','context:geometric-nature-meets-geometry','context:geometric-optical-illusion-and-depth','context:geometric-pattern-and-tessellation','context:geometric-pure-geometry','context:geometric-push-geometric','context:geometric-radial-geometry-and-joints','context:geometric-wrap-rotation-and-movement')
$tmp = Join-Path $env:TEMP "aura-ctx-geometric.json"
